#include <bits/stdc++.h>
using namespace std;
void solve(){
    long long n;
    cin>>n;
    long long totalstud=3*n;
    vector<long long> a(totalstud);
    for(long long &x:a){
        cin>>x;
    }
    sort(a.rbegin(),a.rend());
    vector<long long > pref(totalstud+1,0);
    for(int i=0;i<totalstud;++i){
        pref[i+1]=pref[i]+a[i];
    }
    auto cals=[&](long long A,long long B)-> long long{
        return 2LL*pref[A] +pref[A+2*B] +3LL * pref[3*n-2*A-B];
    };
    long long maxans=0;
    for (long long A=0;A<=n;++A){
        long long maxb=n-A;
        long long low=0,high=maxb-1;
        long long optb=0;
        while(low<=high){
            long long mid=low+(high-low)/2;
            long long delta=a[A+2*mid]+a[A+2*mid+1]-3LL*a[totalstud-2*A-mid-1];
            if(delta>=0){
                optb=mid+1;
                low=mid+1;
                
            }
            else{
                high=mid-1;
            }
        }
        long long startb=max(0LL,optb-2);
        long long endb=min(maxb,optb+2);
        for(long long B=startb;B<=endb;++B){
            maxans=max(maxans ,cals(A,B));
        }
    }
    cout<<maxans<<"\n";
}
int main() {
	// your code goes here
	int t;
	if(cin>>t){
	    while(t--){
	        solve();
	    }
	}
   return 0;
}
